<script>document.documentElement.classList.add('js');document.addEventListener('DOMContentLoaded',()=>{const shell=document.querySelector('.product-export-page');const form=document.getElementById('productExportForm');const result=document.getElementById('productExportResult');const root=document.getElementById('root-category');const child=document.getElementById('subcategory');let aborter;let childAborter;let timer;const params=()=>new URLSearchParams(new FormData(form));const refresh=()=>{clearTimeout(timer);timer=setTimeout(async()=>{aborter?.abort();aborter=new AbortController();result.classList.add('is-loading');try{const qs=params();const r=await fetch(`${shell.dataset.dataUrl}?${qs}`,{headers:{'Accept':'text/html','X-Requested-With':'XMLHttpRequest'},signal:aborter.signal});if(!r.ok)throw new Error(r.status);const loading=result.querySelector('.catalog-loading')?.outerHTML||'';result.innerHTML=loading+await r.text();history.replaceState({},'',`${form.action}?${qs}`)}catch(e){if(e.name!=='AbortError')result.insertAdjacentHTML('afterbegin','<div class="alert alert-danger m-3">دریافت اطلاعات با خطا روبه‌رو شد.</div>')}finally{result.classList.remove('is-loading')}},300)};const loadChildren=async()=>{childAborter?.abort();childAborter=new AbortController();child.innerHTML='<option value="">در حال بارگیری...</option>';child.disabled=true;const rootId=root.value;if(!rootId){child.innerHTML='<option value="">همه زیردسته‌ها</option>';child.disabled=false;refresh();return}try{const url=shell.dataset.childrenUrlTemplate.replace('__ID__',rootId);const r=await fetch(url,{headers:{'Accept':'application/json'},signal:childAborter.signal});const data=await r.json();child.innerHTML='<option value="">همه زیردسته‌ها</option>';data.items.forEach(item=>child.add(new Option(item.name,item.id)));}finally{child.disabled=false;refresh();}};root.addEventListener('change',()=>{child.dataset.selected='';loadChildren()});form.addEventListener('change',e=>{if(e.target!==root)refresh()});form.addEventListener('submit',e=>{e.preventDefault();refresh()});document.getElementById('printProductsButton')?.addEventListener('click',()=>{location.assign(`${shell.dataset.printUrl}?${params()}`)});window.addEventListener('popstate',()=>location.reload())});</script>
